```tsx
import "./ProblemTable.css";

export interface ProblemRow {
  title: string;
  pattern: string;
  minutes: number;
  review: string;
  due: boolean;
}

export interface ProblemTableProps {
  rows: readonly ProblemRow[];
}

export function ProblemTable({ rows }: ProblemTableProps) {
  return (
    <div
      className="problem-table-scroll"
      role="region"
      aria-label="Solved problems, scrollable"
      tabIndex={0}
    >
      <table className="problem-table">
        <caption className="sr-only">Solved problems and their next review</caption>
        <thead>
          <tr>
            <th scope="col">Title</th>
            <th scope="col">Pattern</th>
            <th scope="col" className="num">Minutes</th>
            <th scope="col">Next review</th>
          </tr>
        </thead>
        <tbody>
          {rows.map((row, index) => (
            <tr key={`${row.title}-${index}`}>
              <td>{row.title}</td>
              <td>{row.pattern}</td>
              <td className="num">{row.minutes}</td>
              <td className={row.due ? "review is-due" : "review"}>
                {row.review}
                {row.due && <span className="due-tag">due</span>}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
```

```css
.problem-table-scroll {
  overflow-x: auto;
  background: var(--slide);
}

.problem-table-scroll:focus-visible {
  outline: 3px solid var(--cresyl);
  outline-offset: 3px;
}

.problem-table {
  width: 100%;
  border-collapse: collapse;
  color: var(--ink);
  font-size: clamp(0.875rem, 0.8rem + 0.3vw, 1rem);
}

.problem-table th,
.problem-table td {
  text-align: left;
  padding: 0.6em 0.8em;
  border-bottom: 1px solid var(--hair);
  vertical-align: middle;
}

.problem-table th {
  color: var(--muted);
  font-weight: 600;
  border-bottom-width: 1px;
}

.problem-table tbody tr:hover {
  background: var(--myelin-wash);
}

.problem-table .num {
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.problem-table .is-due {
  background: var(--cresyl-wash);
  font-weight: 600;
}

.due-tag {
  display: inline-block;
  margin-left: 0.5em;
  padding: 0.1em 0.6em;
  border: 1px solid var(--cresyl);
  border-radius: 999px;
  color: var(--ink);
  font-size: 0.8em;
  font-weight: 600;
  line-height: 1.4;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}
